[{"order":1,"type":"heading","text":"Mixins and Composition Patterns in TypeScript"},{"order":2,"type":"paragraph","text":"TypeScript offers powerful ways to reuse code. While traditional object-oriented programming relies heavily on class inheritance (extends), composition patterns and mixins provide a more flexible approach to building complex behaviors without deep inheritance hierarchies."},{"order":3,"type":"subheading","text":"Understanding the Limitations of Classical Inheritance"},{"order":4,"type":"paragraph","text":"JavaScript and TypeScript are single-inheritance languages. A class can only extend one other class. This becomes problematic when you want to share unrelated behaviors across multiple distinct classes, leading to rigid taxonomies and bloated base classes."},{"order":5,"type":"subheading","text":"What is a Mixin?"},{"order":6,"type":"paragraph","text":"A mixin is a function that takes a constructor, creates a new class that extends it with new capabilities, and returns the augmented class. This allows you to compose behaviors dynamically."},{"order":7,"type":"code","text":"type Constructor<T = {}> = new (...args: any[]) => T;

function Timestamped<TBase extends Constructor>(Base: TBase) {
  return class extends Base {
    timestamp = new Date();
  };
}

function Activatable<TBase extends Constructor>(Base: TBase) {
  return class extends Base {
    isActive = false;
    toggle() {
      this.isActive = !this.isActive;
    }
  };
}"},{"order":8,"type":"subheading","text":"Applying Mixins to a Class"},{"order":9,"type":"paragraph","text":"To apply mixins, you create a base class and successively wrap it with your mixin functions. TypeScript infers the combined types automatically."},{"order":10,"type":"code","text":"class User {
  constructor(public name: string) {}
}

// Compose the mixins
const TimedActiveUser = Activatable(Timestamped(User));

const user = new TimedActiveUser("Alice");
console.log(user.name);
console.log(user.timestamp);
user.toggle();
console.log(user.isActive);"},{"order":11,"type":"subheading","text":"Best Practices for Composition"},{"order":12,"type":"bullet_point","text":"Keep mixins small and focused on a single responsibility (e.g., Logging, Persistence, Validation)."},{"order":13,"type":"bullet_point","text":"Use generic constraints (Constructor<T>) to ensure type safety across mixed classes."},{"order":14,"type":"bullet_point","text":"Prefer composition over deep inheritance trees to maintain loosely coupled code."}]
